$global:FeatureLang = $global:FeatureLangJson | ConvertFrom-Json

# 7. Build WPF XAML Interface with Search, Live HUD, Presets & Software Hub
[xml]$xaml = @"
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
        xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        Name="MainWindow"
        Title="MephistoCleaner v7.0 Ultimate - Modular Windows Optimization &amp; Gaming Suite" 
        Height="870" Width="1180" 
        WindowStartupLocation="CenterScreen" 
        Background="#0F141C" 
        Foreground="#E0E6ED"
        FontFamily="Segoe UI">
    <Window.Resources>
        <Style TargetType="ToolTip">
            <Setter Property="Background" Value="#1E293B"/>
            <Setter Property="Foreground" Value="#38BDF8"/>
            <Setter Property="BorderBrush" Value="#0EA5E9"/>
            <Setter Property="BorderThickness" Value="1"/>
            <Setter Property="FontSize" Value="12"/>
            <Setter Property="Padding" Value="8,5"/>
        </Style>
        <Style TargetType="Button">
            <Setter Property="Background" Value="#1E293B"/>
            <Setter Property="Foreground" Value="#F8FAFC"/>
            <Setter Property="FontSize" Value="11"/>
            <Setter Property="FontWeight" Value="SemiBold"/>
            <Setter Property="Padding" Value="6,4"/>
            <Setter Property="Margin" Value="2"/>
            <Setter Property="BorderThickness" Value="1"/>
            <Setter Property="BorderBrush" Value="#334155"/>
            <Setter Property="Cursor" Value="Hand"/>
        </Style>
        <Style TargetType="TabItem">
            <Setter Property="FontSize" Value="11.5"/>
            <Setter Property="FontWeight" Value="Bold"/>
            <Setter Property="Foreground" Value="#94A3B8"/>
            <Setter Property="Padding" Value="9,5"/>
            <Setter Property="Background" Value="#0F141C"/>
        </Style>
        <Style TargetType="CheckBox">
            <Setter Property="Foreground" Value="#F8FAFC"/>
            <Setter Property="FontSize" Value="11.5"/>
            <Setter Property="Margin" Value="4"/>
            <Setter Property="Cursor" Value="Hand"/>
        </Style>
    </Window.Resources>

    <Grid Margin="10">
        <Grid.RowDefinitions>
            <RowDefinition Height="Auto"/> <!-- Row 0: Top Header -->
            <RowDefinition Height="Auto"/> <!-- Row 1: Live Hardware HUD -->
            <RowDefinition Height="Auto"/> <!-- Row 2: Presets & Search Bar -->
            <RowDefinition Height="*"/>    <!-- Row 3: Tabs (150 Features + Software Hub) -->
            <RowDefinition Height="120"/>  <!-- Row 4: Console Log -->
        </Grid.RowDefinitions>

        <!-- ROW 0: TOP HEADER -->
        <Border Grid.Row="0" Name="HeaderBorder" Background="#1E293B" CornerRadius="8" Padding="10,8" Margin="0,0,0,6" BorderBrush="#334155" BorderThickness="1">
            <Grid>
                <Grid.ColumnDefinitions>
                    <ColumnDefinition Width="*"/>
                    <ColumnDefinition Width="Auto"/>
                </Grid.ColumnDefinitions>
                
                <StackPanel Grid.Column="0" VerticalAlignment="Center">
                    <StackPanel Orientation="Horizontal">
